1	/**
2	 * ExcelGrid — reusable Excel-like selection, navigation, editing and
3	 * clipboard for any Reflex-rendered numeric grid.
4	 *
5	 * The children render the grid (any markup). Editable rows carry
6	 *   data-row-key="<unique row key>" data-block="<group key, optional>"
7	 * and editable cells inside them carry
8	 *   data-cell-key="<unique cell key>" data-col="<column key>" data-value="<number>".
9	 * Rows of the same block form one "data region" for Ctrl+Arrow and Ctrl+A.
10	 * Everything interactive happens in the browser; only committed batches are
11	 * sent to the server through `onCommit([{key, value}])`. Invalid pasted cells
12	 * are reported through `onReject(count)`.
13	 *
14	 * Dragging the fill handle (bottom-right corner of the selection) repeats the
15	 * selected values into the dragged-over cells, like Excel. Editable cells need
16	 * a positioning context; the handle cell gets `position: relative`.
17	 *
18	 * While `dirty` is true, leaving the route (links, redirects, Back) is held
19	 * by a React Router blocker and the user can stay, discard or save & leave;
20	 * closing/reloading the tab triggers the browser's beforeunload prompt.
21	 */
22	import React, { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
23	import { Button, Group, Modal, Text } from "@mantine/core";
24	import { useBlocker } from "react-router";
25	import * as G from "./grid_logic.js";
26	
27	const FOCUS_RING = "inset 0 0 0 2px var(--mantine-color-blue-6)";
28	const RANGE_FILL = "inset 0 0 0 999px light-dark(rgba(34, 139, 230, 0.14), rgba(34, 139, 230, 0.24))";
29	const FILL_HANDLE =
30	  'content:"";position:absolute;right:-4px;bottom:-4px;width:7px;height:7px;z-index:1;' +
31	  "box-sizing:border-box;cursor:crosshair;background:var(--mantine-color-blue-6);" +
32	  "border:1px solid var(--alloq-surface-solid, #fff);";
33	const FILL_PREVIEW = "outline:1px dashed var(--mantine-color-blue-6);outline-offset:-1px;";
34	const HANDLE_HIT_PX = 5;
35	const ROW_PX = 32;
36	// Attributes that define the grid layout (see the header comment).
37	const LAYOUT_ATTRS = ["data-row-key", "data-block", "data-cell-key", "data-col"];
38	// How long an optimistic value may wait for the server to confirm it.
39	const PENDING_TTL_MS = 5000;
40	
41	function readLayout(root) {
42	  const rows = [];
43	  const els = new Map();
44	  let cols = [];
45	  root.querySelectorAll("[data-row-key]").forEach((rowEl) => {
46	    const cells = [];
47	    rowEl.querySelectorAll("[data-cell-key]").forEach((el) => {
48	      const key = el.getAttribute("data-cell-key");
49	      cells.push(key);
50	      els.set(key, el);
51	    });
52	    if (cells.length) {
53	      if (!rows.length) cols = cells.map((k) => els.get(k).getAttribute("data-col") || "");
54	      rows.push({
55	        key: rowEl.getAttribute("data-row-key"),
56	        block: rowEl.getAttribute("data-block") || "",
57	        cells,
58	      });
59	    }
60	  });
61	  return { rows, els, cols };
62	}
63	
64	function attr(value) {
65	  // Also escapes newlines, which would otherwise end the quoted value early.
66	  return CSS.escape(String(value));
67	}
68	
69	function rectRule(root, layout, rect, decl) {
70	  // Column keys come from data-col on the cells of the first row.
71	  const rowSel = [];
72	  for (let r = rect.r0; r <= rect.r1; r++) {
73	    rowSel.push(`[data-row-key="${attr(layout.rows[r].key)}"]`);
74	  }
75	  const colSel = [];
76	  for (let c = rect.c0; c <= rect.c1; c++) {
77	    colSel.push(`[data-col="${attr(layout.cols[c])}"]`);
78	  }
79	  return `${root} :is(${rowSel.join(",")}) :is(${colSel.join(",")}){${decl}}`;
80	}
81	
82	function selectionCss(id, layout, sel, { handle, fill }) {
83	  if (!sel.focusKey || !layout.rows.length) return "";
84	  const root = `#${CSS.escape(id)}`;
85	  const f = G.findPos(layout, sel.focusKey);
86	  if (!f) return "";
87	  const a = G.findPos(layout, sel.anchorKey) || f;
88	  const rect = G.normalizeRange(a, f);
89	  let css = "";
90	  if (a.r !== f.r || a.c !== f.c) css += rectRule(root, layout, rect, `box-shadow:${RANGE_FILL};`);
91	  css += `${root} [data-cell-key="${attr(sel.focusKey)}"]{box-shadow:${FOCUS_RING};}`;
92	  if (handle) {
93	    const cell = `${root} [data-cell-key="${attr(G.keyAt(layout, { r: rect.r1, c: rect.c1 }))}"]`;
94	    css += `${cell}{position:relative;}${cell}::after{${FILL_HANDLE}}`;
95	  }
96	  if (fill) {
97	    css += rectRule(root, layout, fill, FILL_PREVIEW);
98	    css += `${root},${root} *{cursor:crosshair !important;}`;
99	  }
100	  return css;
101	}
102	
103	function sameRect(a, b) {
104	  if (!a || !b) return a === b;
105	  return a.r0 === b.r0 && a.r1 === b.r1 && a.c0 === b.c0 && a.c1 === b.c1;
106	}
107	
108	function scrollIntoViewIfNeeded(root, el) {
109	  if (!root || !el) return;
110	  const header = root.querySelector("[data-grid-header]");
111	  const headerH = header ? header.getBoundingClientRect().height : 0;
112	  const rowEl = el.closest("[data-row-key]");
113	  const label = rowEl ? rowEl.firstElementChild : null;
114	  const labelW = label && label !== el ? label.getBoundingClientRect().width : 0;
115	  const rr = root.getBoundingClientRect();
116	  const cr = el.getBoundingClientRect();
117	  if (cr.bottom > rr.bottom - 2) root.scrollTop += cr.bottom - rr.bottom + 2;
118	  else if (cr.top < rr.top + headerH) root.scrollTop -= rr.top + headerH - cr.top + 2;
119	  if (cr.right > rr.right - 2) root.scrollLeft += cr.right - rr.right + 2;
120	  else if (cr.left < rr.left + labelW) root.scrollLeft -= rr.left + labelW - cr.left + 2;
121	}
122	
123	export function ExcelGrid({
124	  id,
125	  ref,
126	  children,
127	  className,
128	  onCommit,
129	  onSave,
130	  onReject,
131	  revision,
132	  dirty,
133	  gridLabel,
134	  minValue = 0,
135	  maxValue,
136	  decimals = 2,
137	  decimalSeparator = ",",
138	  invalidMessage = "Ungültige Zahl",
139	  saving = false,
140	  leaveTitle = "Ungespeicherte Änderungen",
141	  leaveMessage = "Es gibt ungespeicherte Änderungen. Möchtest du die Seite wirklich verlassen?",
142	  leaveStayLabel = "Bleiben",
143	  leaveDiscardLabel = "Verwerfen",
144	  leaveSaveLabel = "Speichern & verlassen",
145	}) {
146	  const parseOpts = { min: minValue, max: maxValue ?? Infinity, decimals };
147	  const formatOpts = { decimals, separator: decimalSeparator };
148	  const rootRef = useRef(null);
149	  const inputRef = useRef(null);
150	  const layoutRef = useRef(null);
151	  const pendingRef = useRef(new Map());
152	  const undoRef = useRef([]);
153	  const redoRef = useRef([]);
154	  const dragRef = useRef(false);
155	  const closingRef = useRef(false);
156	  const [sel, setSel] = useState({ anchorKey: null, focusKey: null, block: null });
157	  const [editor, setEditor] = useState(null); // {key, value, mode, invalid, box}
158	  const [fill, setFill] = useState(null); // fill-handle drag: {src, target}
159	  const [layoutVersion, setLayoutVersion] = useState(0);
160	
161	  // React 19: `ref` arrives as a prop (Reflex passes one when `id` is set).
162	  const setRootRef = useCallback(
163	    (node) => {
164	      rootRef.current = node;
165	      if (typeof ref === "function") ref(node);
166	      else if (ref) ref.current = node;
167	    },
168	    [ref],
169	  );
170	
171	  // --- layout cache -------------------------------------------------------
172	
173	  const layout = useCallback(() => {
174	    if (!layoutRef.current && rootRef.current) layoutRef.current = readLayout(rootRef.current);
175	    return layoutRef.current || { rows: [], els: new Map(), cols: [] };
176	  }, []);
177	
178	  const getValue = useCallback(
179	    (key) => {
180	      if (pendingRef.current.has(key)) return pendingRef.current.get(key);
181	      const el = layout().els.get(key);
182	      return el ? Number(el.getAttribute("data-value")) || 0 : 0;
183	    },
184	    [layout],
185	  );
186	
187	  useEffect(() => {
188	    const root = rootRef.current;
189	    if (!root) return undefined;
190	    const observer = new MutationObserver((records) => {
191	      // Rows/cells reused by React keep their nodes but get new keys, so key
192	      // attribute changes invalidate the cached key -> element map as well.
193	      if (records.some((r) => r.type === "childList" || LAYOUT_ATTRS.includes(r.attributeName))) {
194	        layoutRef.current = null;
195	        setLayoutVersion((v) => v + 1);
196	      }
197	      const pending = pendingRef.current;
198	      if (pending.size) {
199	        const els = layout().els;
200	        for (const [key, value] of pending) {
201	          const el = els.get(key);
202	          if (!el || Number(el.getAttribute("data-value")) === value) pending.delete(key);
203	        }
204	      }
205	    });
206	    observer.observe(root, { childList: true, subtree: true, attributes: true, attributeFilter: ["data-value", ...LAYOUT_ATTRS] });
207	    return () => observer.disconnect();
208	  }, [layout]);
209	
210	  useEffect(() => {
211	    undoRef.current = [];
212	    redoRef.current = [];
213	    pendingRef.current.clear();
214	    layoutRef.current = null;
215	  }, [revision]);
216	
217	  useEffect(() => {
218	    if (!dirty) return undefined;
219	    const handler = (e) => {
220	      e.preventDefault();
221	      e.returnValue = "";
222	    };
223	    window.addEventListener("beforeunload", handler);
224	    return () => window.removeEventListener("beforeunload", handler);
225	  }, [dirty]);
226	
227	  // --- in-app navigation guard (links, redirects, Back) -------------------
228	
229	  const blocker = useBlocker(
230	    ({ currentLocation, nextLocation }) =>
231	      Boolean(dirty) && currentLocation.pathname !== nextLocation.pathname,
232	  );
233	  const blocked = blocker.state === "blocked";
234	  const [leaveSaving, setLeaveSaving] = useState(false);
235	  const sawSavingRef = useRef(false);
236	
237	  useEffect(() => {
238	    if (!blocked) {
239	      setLeaveSaving(false);
240	      return;
241	    }
242	    if (!dirty) {
243	      // Saved (or nothing left to lose) while the dialog was open.
244	      blocker.proceed();
245	    } else if (leaveSaving) {
246	      if (saving) sawSavingRef.current = true;
247	      else if (sawSavingRef.current) {
248	        // Save finished but changes remain (error) — let the user decide again.
249	        sawSavingRef.current = false;
250	        setLeaveSaving(false);
251	      }
252	    }
253	  }, [blocked, dirty, saving, leaveSaving, blocker]);
254	
255	  const stay = () => blocker.reset?.();
256	  const discard = () => blocker.proceed?.();
257	  const saveAndLeave = () => {
258	    sawSavingRef.current = false;
259	    setLeaveSaving(true);
260	    onSave?.();
261	  };
262	
263	  // --- selection helpers --------------------------------------------------
264	
265	  const current = useCallback(() => {
266	    const lay = layout();
267	    const focus = G.resolvePos(lay, sel.focusKey, sel.block);
268	    if (!focus) return null;
269	    const anchor = G.findPos(lay, sel.anchorKey) || focus;
270	    return { lay, focus, anchor, rect: G.normalizeRange(anchor, focus) };
271	  }, [layout, sel]);
272	
273	  const select = useCallback((lay, focus, anchor = focus) => {
274	    const focusKey = G.keyAt(lay, focus);
275	    const anchorKey = G.keyAt(lay, anchor);
276	    setSel({ anchorKey, focusKey, block: lay.rows[focus.r].block });
277	  }, []);
278	
279	  const selectRect = useCallback(
280	    (lay, rect) => select(lay, { r: rect.r1, c: rect.c1 }, { r: rect.r0, c: rect.c0 }),
281	    [select],
282	  );
283	
284	  useLayoutEffect(() => {
285	    if (!sel.focusKey) return;
286	    scrollIntoViewIfNeeded(rootRef.current, layout().els.get(sel.focusKey));
287	  }, [sel.focusKey, layout]);
288	
289	  const focusRoot = useCallback(() => {
290	    rootRef.current?.focus({ preventScroll: true });
291	  }, []);
292	
293	  // --- committing ---------------------------------------------------------
294	
295	  const applyChanges = useCallback(
296	    (changes, { record = true } = {}) => {
297	      const batch = G.withBefore(changes, getValue);
298	      if (!batch.length) return;
299	      const pending = pendingRef.current;
300	      for (const ch of batch) pending.set(ch.key, ch.after);
301	      onCommit?.(batch.map((ch) => ({ key: ch.key, value: ch.after })));
302	      // A rejected or normalized value never shows up in data-value, so drop
303	      // entries the server did not confirm instead of keeping them forever.
304	      setTimeout(() => {
305	        for (const ch of batch) if (pending.get(ch.key) === ch.after) pending.delete(ch.key);
306	      }, PENDING_TTL_MS);
307	      if (record) {
308	        undoRef.current.push(batch);
309	        if (undoRef.current.length > 200) undoRef.current.shift();
310	        redoRef.current = [];
311	      }
312	    },
313	    [getValue, onCommit],
314	  );
315	
316	  const history = useCallback(
317	    (from, to, field) => {
318	      const batch = from.current.pop();
319	      if (!batch) return;
320	      applyChanges(
321	        batch.map((ch) => ({ key: ch.key, value: ch[field] })),
322	        { record: false },
323	      );
324	      to.current.push(batch);
325	      const lay = layout();
326	      const positions = batch.map((ch) => G.findPos(lay, ch.key)).filter(Boolean);
327	      if (positions.length) selectRect(lay, G.boundingRect(positions));
328	    },
329	    [applyChanges, layout, selectRect],
330	  );
331	
332	  // --- editor -------------------------------------------------------------
333	
334	  const startEdit = useCallback(
335	    (mode, initial) => {
336	      const cur = current();
337	      if (!cur) return;
338	      const key = G.keyAt(cur.lay, cur.focus);
339	      const el = cur.lay.els.get(key);
340	      const root = rootRef.current;
341	      if (!el || !root) return;
342	      scrollIntoViewIfNeeded(root, el);
343	      const rr = root.getBoundingClientRect();
344	      const cr = el.getBoundingClientRect();
345	      const box = {
346	        top: cr.top - rr.top + root.scrollTop - root.clientTop,
347	        left: cr.left - rr.left + root.scrollLeft - root.clientLeft,
348	        width: cr.width,
349	        height: cr.height,
350	      };
351	      const value = initial ?? G.formatNumber(getValue(key), formatOpts);
352	      setSel({ anchorKey: key, focusKey: key, block: cur.lay.rows[cur.focus.r].block });
353	      setEditor({ key, value, mode, invalid: false, box });
354	    },
355	    // eslint-disable-next-line react-hooks/exhaustive-deps
356	    [current, getValue, decimals, decimalSeparator],
357	  );
358	
359	  useLayoutEffect(() => {
360	    const input = inputRef.current;
361	    if (!editor || !input || document.activeElement === input) return;
362	    input.focus({ preventScroll: true });
363	    const end = input.value.length;
364	    input.setSelectionRange(end, end);
365	  }, [editor]);
366	
367	  const closeEditor = useCallback(() => {
368	    closingRef.current = true;
369	    setEditor(null);
370	    focusRoot();
371	    setTimeout(() => {
372	      closingRef.current = false;
373	    }, 0);
374	  }, [focusRoot]);
375	
376	  /** Commit the editor; returns false (and keeps it open) when invalid. */
377	  const commitEditor = useCallback(
378	    (then) => {
379	      if (!editor) return true;
380	      const value = G.parseNumber(editor.value, parseOpts);
381	      if (value === null) {
382	        setEditor({ ...editor, invalid: true });
383	        return false;
384	      }
385	      applyChanges([{ key: editor.key, value }]);
386	      closeEditor();
387	      if (then) then();
388	      return true;
389	    },
390	    // eslint-disable-next-line react-hooks/exhaustive-deps
391	    [editor, applyChanges, closeEditor, minValue, maxValue, decimals],
392	  );
393	
394	  const moveBy = useCallback(
395	    (fn) => {
396	      const lay = layout();
397	      const focus = G.resolvePos(lay, sel.focusKey, sel.block);
398	      if (focus) select(lay, fn(lay, focus));
399	    },
400	    [layout, sel, select],
401	  );
402	
403	  const onEditorKeyDown = (e) => {
404	    e.stopPropagation();
405	    if (e.nativeEvent.isComposing) return;
406	    const arrows = { ArrowUp: "up", ArrowDown: "down", ArrowLeft: "left", ArrowRight: "right" };
407	    if (e.key === "Enter") {
408	      e.preventDefault();
409	      commitEditor(() => moveBy((lay, p) => G.move(lay, p, e.shiftKey ? "up" : "down")));
410	    } else if (e.key === "Tab") {
411	      e.preventDefault();
412	      commitEditor(() => moveBy((lay, p) => G.tabMove(lay, p, e.shiftKey)));
413	    } else if (e.key === "Escape") {
414	      e.preventDefault();
415	      closeEditor();
416	    } else if (e.key === "F2") {
417	      e.preventDefault();
418	      setEditor({ ...editor, mode: editor.mode === "edit" ? "enter" : "edit" });
419	    } else if (arrows[e.key] && editor.mode === "enter") {
420	      e.preventDefault();
421	      commitEditor(() => moveBy((lay, p) => G.move(lay, p, arrows[e.key])));
422	    }
423	  };
424	
425	  const onEditorBlur = () => {
426	    if (closingRef.current || !editor) return;
427	    if (!commitEditor()) closeEditor();
428	  };
429	
430	  // --- keyboard (selection mode) -----------------------------------------
431	
432	  const onKeyDown = (e) => {
433	    if (e.target !== rootRef.current || e.nativeEvent.isComposing) return;
434	    if (fill && e.key === "Escape") {
435	      e.preventDefault();
436	      setFill(null);
437	      return;
438	    }
439	    const cur = current();
440	    if (!cur) return;
441	    const { lay, focus, anchor, rect } = cur;
442	    const mod = e.ctrlKey || e.metaKey;
443	    const key = e.key.length === 1 ? e.key.toLowerCase() : e.key;
444	    const arrows = { ArrowUp: "up", ArrowDown: "down", ArrowLeft: "left", ArrowRight: "right" };
445	    let handled = true;
446	
447	    if (arrows[key] || key === "Home" || key === "End") {
448	      const dir = arrows[key] || key.toLowerCase();
449	      const next = G.move(lay, focus, dir, { ctrl: mod });
450	      select(lay, next, e.shiftKey ? anchor : next);
451	    } else if (key === "PageDown" || key === "PageUp") {
452	      const rows = Math.floor((rootRef.current.clientHeight || ROW_PX) / ROW_PX) - 4;
453	      const next = G.pageMove(lay, focus, rows, key === "PageUp");
454	      select(lay, next, e.shiftKey ? anchor : next);
455	    } else if (key === "Tab") {
456	      select(lay, G.tabMove(lay, focus, e.shiftKey));
457	    } else if (key === "Enter" && !mod) {
458	      select(lay, G.move(lay, focus, e.shiftKey ? "up" : "down"));
459	    } else if (key === "F2") {
460	      startEdit("edit");
461	    } else if (key === "Delete" || key === "Backspace") {
462	      applyChanges(G.planClear(lay, rect));
463	    } else if (key === "Escape") {
464	      select(lay, focus);
465	    } else if (mod && key === "a") {
466	      const block = G.blockRect(lay, focus.r);
467	      const same = ["r0", "r1", "c0", "c1"].every((k) => block[k] === rect[k]);
468	      selectRect(lay, same ? G.allRect(lay) : block);
469	    } else if (mod && (key === "y" || (key === "z" && e.shiftKey))) {
470	      history(redoRef, undoRef, "after");
471	    } else if (mod && key === "z") {
472	      history(undoRef, redoRef, "before");
473	    } else if (mod && (key === "d" || key === "r")) {
474	      applyChanges(G.planFill(lay, rect, key === "d" ? "down" : "right", getValue));
475	    } else if (mod && key === "s") {
476	      onSave?.();
477	    } else if (mod && (key === "c" || key === "x" || key === "v")) {
478	      handled = false; // handled by the native clipboard events below
479	    } else if (e.key.length === 1 && !mod && !e.altKey) {
480	      startEdit("enter", e.key);
481	    } else {
482	      handled = false;
483	    }
484	    if (handled) e.preventDefault();
485	  };
486	
487	  // --- clipboard (native events; no permission prompt) --------------------
488	
489	  useEffect(() => {
490	    const isActive = () => document.activeElement === rootRef.current;
491	    const copy = (e, cut) => {
492	      if (!isActive()) return;
493	      const cur = current();
494	      if (!cur) return;
495	      const matrix = [];
496	      for (let r = cur.rect.r0; r <= cur.rect.r1; r++) {
497	        const row = [];
498	        for (let c = cur.rect.c0; c <= cur.rect.c1; c++) row.push(getValue(G.keyAt(cur.lay, { r, c })));
499	        matrix.push(row);
500	      }
501	      e.clipboardData.setData("text/plain", G.toTSV(matrix, formatOpts));
502	      e.preventDefault();
503	      if (cut) applyChanges(G.planClear(cur.lay, cur.rect));
504	    };
505	    const onCopy = (e) => copy(e, false);
506	    const onCut = (e) => copy(e, true);
507	    const onPaste = (e) => {
508	      if (!isActive()) return;
509	      const cur = current();
510	      if (!cur) return;
511	      e.preventDefault();
512	      const matrix = G.parseTSV(e.clipboardData.getData("text/plain"));
513	      const plan = G.planPaste(cur.lay, cur.rect, matrix, parseOpts);
514	      applyChanges(plan.changes);
515	      selectRect(cur.lay, plan.rect);
516	      if (plan.skipped) onReject?.(plan.skipped);
517	    };
518	    document.addEventListener("copy", onCopy);
519	    document.addEventListener("cut", onCut);
520	    document.addEventListener("paste", onPaste);
521	    return () => {
522	      document.removeEventListener("copy", onCopy);
523	      document.removeEventListener("cut", onCut);
524	      document.removeEventListener("paste", onPaste);
525	    };
526	    // eslint-disable-next-line react-hooks/exhaustive-deps
527	  }, [current, getValue, applyChanges, selectRect, onReject, minValue, maxValue, decimals, decimalSeparator]);
528	
529	  // --- mouse --------------------------------------------------------------
530	
531	  const cellFromEvent = (e) => {
532	    if (e.target.closest("button, a, input, [role='button']")) return null;
533	    const el = e.target.closest("[data-cell-key]");
534	    return el && rootRef.current?.contains(el) ? el.getAttribute("data-cell-key") : null;
535	  };
536	
537	  /** Selection rect when the pointer is on the fill handle, else null. */
538	  const handleHit = (e) => {
539	    if (editor || !sel.focusKey) return null;
540	    const cur = current();
