543	    const cr = el.getBoundingClientRect();
544	    const hit =
545	      Math.abs(e.clientX - cr.right) <= HANDLE_HIT_PX && Math.abs(e.clientY - cr.bottom) <= HANDLE_HIT_PX;
546	    return hit ? cur.rect : null;
547	  };
548	
549	  const onMouseDown = (e) => {
550	    if (e.button !== 0) return;
551	    const src = handleHit(e);
552	    if (src) {
553	      e.preventDefault();
554	      focusRoot();
555	      setFill({ src, target: null });
556	      return;
557	    }
558	    const key = cellFromEvent(e);
559	    if (!key) return;
560	    e.preventDefault();
561	    if (editor) {
562	      if (editor.key === key) return;
563	      if (!commitEditor()) closeEditor();
564	    }
565	    focusRoot();
566	    const lay = layout();
567	    const pos = G.findPos(lay, key);
568	    if (!pos) return;
569	    const anchor = e.shiftKey ? G.findPos(lay, sel.anchorKey) || pos : pos;
570	    select(lay, pos, anchor);
571	    dragRef.current = true;
572	  };
573	
574	  const onMouseOver = (e) => {
575	    if (fill) {
576	      const key = cellFromEvent(e);
577	      const pos = key && G.findPos(layout(), key);
578	      if (!pos) return;
579	      const target = G.fillHandleRect(fill.src, pos);
