581	      return;
582	    }
583	    if (!dragRef.current) return;
584	    const key = cellFromEvent(e);
585	    if (!key || key === sel.focusKey) return;
586	    const lay = layout();
587	    const pos = G.findPos(lay, key);
588	    const anchor = G.findPos(lay, sel.anchorKey);
589	    if (pos && anchor) select(lay, pos, anchor);
590	  };
591	
592	  useEffect(() => {
593	    const up = () => {
594	      dragRef.current = false;
595	    };
596	    window.addEventListener("mouseup", up);
